                    _ = self.abortOnWorkerPanic(idx, status);
                }
            }
            var respawned = false;
            _ = &respawned;
            if (((!self.bailed) and self.hasUndispatchedFiles())) {
                _ = w.ipc.deinit();
                _ = w.out.deinit();
                _ = w.err.deinit();
                w.ipc = .{};
                w.out = .{ .role = .stdout, .worker = w };
                w.err = .{ .role = .stderr, .worker = w };
                w.process = null;
                var start_ok = true;
                _ = &start_ok;
                _ = (blk_catch_8: { break :blk_catch_8 ((w.start()) catch |e| { _ = &e; _ = Output.err(e, "failed to respawn test worker", .{});
                start_ok = false;
                break :blk_catch_8 {}; }); });
                if (start_ok) {
                    respawned = true;
                }
            }
            if ((!respawned)) {
                if (((!self.bailed) and (self.live_workers == 0))) {
                    _ = self.abortQueuedFiles("no live workers");
                }
                _ = w.ipc.deinit();
                _ = w.out.deinit();
                _ = w.err.deinit();
                _ = w.captured.deinit(bun.default_allocator);
            }
    }

pub fn accountCrash(self: *Coordinator, file_idx: u32, detail: []const u8) void {
            _ = self.breakDots();
            _ = Output.prettyError("<r><red>✗<r> <b>{s}<r> <d>({s})<r>\n", .{ self.relPath(file_idx), detail });
            self.reporter.summary().fail = (self.reporter.summary().fail + 1);
            self.reporter.summary().files = (self.reporter.summary().files + 1);
            _ = bun.handleOom(self.crashed_files.append(bun.default_allocator, file_idx));
            self.files_done = (self.files_done + 1);
            if (((self.bail > 0) and (self.reporter.summary().fail >= self.bail))) {
                _ = self.bailOut();
            }
    }

pub fn isPanicStatus(status: bun.spawn.Status) bool {
            if (status.signalCode()) |sig| {
                _ = &sig;
                return (switch (sig) {
.SIGILL, .SIGTRAP, .SIGABRT, .SIGBUS, .SIGFPE, .SIGSEGV, .SIGSYS => true,
else => false,
});
            }
            if ((Environment.isWindows and (status == .exited))) {
                return isFatalWindowsExitCode(status.exited.raw);
            }
            return false;
    }

pub fn isFatalWindowsExitCode(code: u32) bool {
            return (switch (code) {
2147483651, 2147483652, 3221225477, 3221225478, 3221225501, 3221225509, 3221225612, 3221225613...3221225619, 3221225620, 3221225621, 3221225622, 3221225725, 3221226356, 3221226505, 3221226519, 3221226525, 3221226528, 3221227010 => true,
else => false,
});
    }

pub fn describeStatus(buf: []u8, status: bun.spawn.Status) []const u8 {
            return (switch (status) {
.exited => |e| blk: {
            const code: u32 = (if (Environment.isWindows) e.raw else e.code);
            if ((code >= 2147483648)) {
                break :blk ((std.fmt.bufPrint(buf, "exit code 0x{X:0>8}", .{ code })) catch unreachable);
            }
            break :blk ((std.fmt.bufPrint(buf, "exit code {d}", .{ code })) catch unreachable);
},
.signaled => |sig| blk: {
            const sigName = (if (@typeInfo(@TypeOf(@TypeOf(sig))) == .@"enum" or @typeInfo(@TypeOf(@TypeOf(sig))) == .@"union") @tagName(@TypeOf(sig)) else @TypeOf(sig).name);
            break :blk ((sigName(sig)) orelse (((std.fmt.bufPrint(buf, "signal {d}", .{ @intFromEnum(sig) })) catch unreachable)));
},
.err => |e| @tagName(e.getErrno()),
.running => "running",
});
    }

pub fn abortOnWorkerPanic(self: *Coordinator, file_idx: u32, status: bun.spawn.Status) void {
            _ = self.breakDots();
            var buf: [32]u8 = undefined;
            _ = &buf;
            _ = Output.prettyError(("\n<red>error<r>: a test worker process crashed with <b>{s}<r> while running <b>{s}<r>.\n" ++ "This indicates a bug in Bun || in a native addon, not in the test itself. Aborting.\n"), .{ Coordinator.describeStatus((&buf), status), self.relPath(file_idx) });
            _ = Output.flush();
            const spawned_workers = self.workers[0..self.spawned_count];
            for (cp_mut_slice(&spawned_workers)) |*other| {
                _ = &other;
                if ((!(other.*).alive)) {
                    continue;
                }
                if ((other.*).process) |p| {
                    _ = &p;
                    if (Environment.isPosix) {
                        const pid = p.pid;
                        _ = std.c.kill((-pid), std.posix.SIG.TERM);
                    } else {
                        _ = p.kill(9);
                    }
                }
            }
            if (self.bailed) {
                return;
            }
            self.bailed = true;
            _ = self.abortQueuedFiles("aborted: worker panicked");
    }

pub fn abortQueuedFiles(self: *Coordinator, reason: []const u8) void {
            const workers = self.workers;
            for (cp_mut_slice(&workers)) |*w| {
                _ = &w;
                while ((w.*).range.popFront()) |idx| {
                    _ = Output.prettyError("<r><red>✗<r> <b>{s}<r> <d>({s})<r>\n", .{ self.relPath(idx), reason });
                    self.reporter.summary().fail = (self.reporter.summary().fail + 1);
                    self.reporter.summary().files = (self.reporter.summary().files + 1);
                    _ = bun.handleOom(self.crashed_files.append(bun.default_allocator, idx));
                    self.files_done = (self.files_done + 1);
                }
            }
            _ = Output.flush();
    }

pub fn assignWorkOrRetry(self: *Coordinator, w: *Worker) void {
            _ = self.assignWork(w);
    }

pub fn createWindowsKillOnCloseJob() ?std.os.windows.HANDLE {
            if ((!Environment.isWindows)) {
                return null;
            }
            const job = ((bun.windows.CreateJobObjectA(null, null)) orelse { return null; });
            var jeli = std.mem.zeroes(bun.c.JOBOBJECT_EXTENDED_LIMIT_INFORMATION);
            _ = &jeli;
            jeli.BasicLimitInformation.LimitFlags = bun.c.JOB_OBJECT_LIMIT_KILL_ON_JOB_CLOSE;
            if ((bun.c.SetInformationJobObject(job, bun.c.JobObjectExtendedLimitInformation, (&jeli), @sizeOf(bun.c.JOBOBJECT_EXTENDED_LIMIT_INFORMATION)) == 0)) {
                _ = std.os.windows.CloseHandle(job);
                return null;
            }
            return job;
    }
    pub const AbortHandler = CoordinatorAbortHandler;
};

